package dev.astralreach.hytale;
import com.hypixel.hytale.codec.*;
import com.hypixel.hytale.codec.builder.BuilderCodec;
import com.hypixel.hytale.component.Resource;
import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;
import dev.astralreach.core.*;
import org.bson.*;
import java.util.*;
/** Saved station ownership, stable external airlocks and moored spacecraft. */
public final class StationRegistry implements Resource<EntityStore>{
 record Mooring(UUID player,int port,LaunchPlan plan){Mooring{Objects.requireNonNull(player);Objects.requireNonNull(plan);StationLayout.checkPort(port);}}
 static final class Station{
  final UUID owner;final String name;final StationLayout layout;final Map<UUID,String>crew=new LinkedHashMap<>();final Map<UUID,Mooring>moorings=new LinkedHashMap<>();int shellVersion;String callSign="";
  String title(){return callSign.isEmpty()?name+"'s station":callSign;}
  void rename(String value){if(value==null)throw new IllegalArgumentException("Enter a station name.");value=value.strip();if(value.isEmpty()||value.length()>32||value.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Use 1–32 printable characters for the station name.");callSign=value;}
  Station(UUID o,String n,int i){this(o,n,i,2);}Station(UUID o,String n,int i,int version){owner=Objects.requireNonNull(o);name=clean(n);layout=new StationLayout(i,version);}
  boolean allows(UUID p){return StationLayout.allowed(owner,crew.keySet(),p);}
  Mooring reserve(UUID player,LaunchPlan plan){if(!allows(player))throw new IllegalArgumentException("This station requires an invitation.");var old=moorings.get(player);if(old!=null){if(old.plan()!=plan)throw new IllegalArgumentException("The saved mooring belongs to another spacecraft.");return old;}int port=player.equals(owner)?StationLayout.OWNER_PORT:-1;var used=new HashSet<Integer>();for(var m:moorings.values())used.add(m.port());if(port<0)for(int i=0;i<StationLayout.PORTS;i++)if(i!=StationLayout.OWNER_PORT&&!used.contains(i)){port=i;break;}if(port<0||used.contains(port))throw new IllegalArgumentException("All visitor airlocks are occupied. Wait for a ship to undock.");var m=new Mooring(player,port,plan);moorings.put(player,m);return m;}
 }
 int nextIndex,skyVersion;final Map<UUID,Station>stations=new LinkedHashMap<>();
 public static final BuilderCodec<StationRegistry>CODEC=BuilderCodec.builder(StationRegistry.class,StationRegistry::new).append(new KeyedCodec<>("StationsV1",Codec.STRING),StationRegistry::restore,StationRegistry::snapshot).add().build();
 public StationRegistry(){}
 static String clean(String n){if(n==null||n.isBlank()||n.length()>64)throw new IllegalArgumentException("Invalid station crew name");return n.replace('\n',' ').replace('\r',' ');}
 String snapshot(){var all=new BsonArray();for(var st:stations.values()){var crew=new BsonDocument();for(var m:st.crew.entrySet())crew.put(m.getKey().toString(),new BsonString(m.getValue()));var moored=new BsonArray();for(var m:st.moorings.values())moored.add(new BsonDocument("Player",new BsonString(m.player().toString())).append("Port",new BsonInt32(m.port())).append("Plan",new BsonString(m.plan().name())));all.add(new BsonDocument("Owner",new BsonString(st.owner.toString())).append("Name",new BsonString(st.name)).append("CallSign",new BsonString(st.callSign)).append("Index",new BsonInt32(st.layout.index())).append("Crew",crew).append("LayoutVersion",new BsonInt32(st.layout.version())).append("ShellVersion",new BsonInt32(st.shellVersion)).append("Moorings",moored));}return new BsonDocument("NextIndex",new BsonInt32(nextIndex)).append("SkyVersion",new BsonInt32(skyVersion)).append("Stations",all).toJson();}
 void restore(String text){stations.clear();nextIndex=0;skyVersion=0;if(text==null||text.isEmpty())return;var root=BsonDocument.parse(text);skyVersion=root.getInt32("SkyVersion",new BsonInt32(0)).getValue();if(skyVersion<0||skyVersion>1)throw new IllegalArgumentException("Invalid orbital environment version");nextIndex=root.getInt32("NextIndex").getValue();if(nextIndex<0||nextIndex>StationLayout.MAX_PLOTS)throw new IllegalArgumentException("Invalid station allocation");var used=new HashSet<Integer>();var parkedPlayers=new HashSet<UUID>();for(var value:root.getArray("Stations")){var d=value.asDocument();var st=new Station(UUID.fromString(d.getString("Owner").getValue()),d.getString("Name").getValue(),d.getInt32("Index").getValue(),d.getInt32("LayoutVersion",new BsonInt32(1)).getValue());var callSign=d.getString("CallSign",new BsonString("")).getValue();if(!callSign.isEmpty())st.rename(callSign);st.shellVersion=d.getInt32("ShellVersion",new BsonInt32(0)).getValue();if(st.shellVersion<0||st.shellVersion>2)throw new IllegalArgumentException("Invalid station structure version");if(st.layout.index()>=nextIndex||!used.add(st.layout.index())||stations.putIfAbsent(st.owner,st)!=null)throw new IllegalArgumentException("Duplicate station allocation");for(var e:d.getDocument("Crew").entrySet()){var id=UUID.fromString(e.getKey());if(id.equals(st.owner)||st.crew.size()>=StationLayout.MAX_CREW)throw new IllegalArgumentException("Invalid station membership");st.crew.put(id,clean(e.getValue().asString().getValue()));}var ports=new HashSet<Integer>();for(var v:d.getArray("Moorings",new BsonArray())){var m=v.asDocument();var id=UUID.fromString(m.getString("Player").getValue());var slot=new Mooring(id,m.getInt32("Port").getValue(),LaunchPlan.restore(m.getString("Plan").getValue()));if(!st.allows(id)||!parkedPlayers.add(id)||!ports.add(slot.port())||st.moorings.putIfAbsent(id,slot)!=null||id.equals(st.owner)!=(slot.port()==StationLayout.OWNER_PORT))throw new IllegalArgumentException("Invalid or duplicate spacecraft mooring");}}}
 @Override public Resource<EntityStore>clone(){var r=new StationRegistry();r.restore(snapshot());return r;}
}
